/* === source: https://royalweedmi.com/assets/front/css/sgen-mobile-menu.css?v=c0b8d1b652bbb60901c5e766d1f79594e3b7002c === */
/* =============================================================================
 * SGEN — Mobile menu drawer (v1, ported from mobile-menu-handoff 2026-05-11)
 *
 * Drill-down sliding-panel drawer. Visible at ≤992px (per DESIGN.md §7k).
 * Uses tenant site-level CSS custom properties directly (no intermediate
 * --sg-* token layer). The mobile menu adapts to each tenant's brand colours
 * and typography automatically. Fallbacks are the SGEN brand-red defaults
 * for tenants that haven't defined the upstream tokens.
 *
 * Tenant tokens consumed (with fallbacks):
 *   --color-primary       (#d51522)     hamburger fill, card accents
 *   --color-primary_hover (#e61938)     gradient companion / tap-hover
 *   --color-primary-rgb   (213, 21, 34) rgba tints (glows, soft fills)
 *   --color-body          (#fff)        drawer + card surface
 *   --color-text          (#1a1a1a)     body text colour
 *   --body-font-family    (Inter)       drawer + card typography
 *   --body-font-size      (18px)        card name size
 *   --button-radius       (12px)        hamburger + close + back buttons
 *
 * See: assets/front/js/sgen-mobile-menu.js (state machine)
 *      DESIGN.md §7k                       (pattern spec)
 *      Mobile-menu-handoff/MOBILE-MENU-HANDOFF.md (origin)
 *
 * All animation is class-driven (no :hover / :active on hamburger/close/back)
 * — JS plays the tap-sequence so touch users see the same theater desktop
 * hover gives.
 * ============================================================================= */


/* =============================================================================
 * Hamburger trigger
 * ============================================================================= */
.mm-hamburger {
    position: relative;
    display: none; /* hidden by default; ≤992px media query reveals it */
    width: 42px;
    height: 42px;
    border: 0;
    padding: 0;
    background: linear-gradient(90deg,
        var(--color-primary, #d51522) 0%,
        var(--color-primary_hover, #e61938) 100%);
    border-radius: var(--button-radius, 12px);
    cursor: pointer;
    box-shadow:
        0 10px 24px rgba(var(--color-primary-rgb, 213, 21, 34), 0.32),
        inset 0 1px 0 rgba(255, 255, 255, 0.22),
        inset 0 -1px 0 rgba(0, 0, 0, 0.22);
    transition:
        transform 0.24s cubic-bezier(.34, 1.56, .64, 1),
        box-shadow 0.24s ease;
    flex-shrink: 0;
    overflow: hidden;
    animation: mm-burger-breathe 3.6s ease-in-out infinite;
    /* Above tenant-page chrome but below the admin topbar (z-index 1000006)
     * so admin links stay clickable when both are visible. */
    z-index: 1000;
}
@keyframes mm-burger-breathe {
    0%, 100% {
        box-shadow:
            0 8px 18px rgba(var(--color-primary-rgb, 213, 21, 34), 0.25),
            inset 0 1px 0 rgba(255, 255, 255, 0.22),
            inset 0 -1px 0 rgba(0, 0, 0, 0.22);
    }
    50% {
        box-shadow:
            0 12px 30px rgba(var(--color-primary-rgb, 213, 21, 34), 0.55),
            inset 0 1px 0 rgba(255, 255, 255, 0.28),
            inset 0 -1px 0 rgba(0, 0, 0, 0.22);
    }
}
/* Shine-sweep — one-shot animation triggered by .is-tap-hover. Not bound to
 * :hover so mobile doesn't fire half-animations on stray pointer events. */
.mm-hamburger::after {
    content: "";
    position: absolute;
    top: 0; left: -120%;
    width: 70%;
    height: 100%;
    background: linear-gradient(
        90deg,
        transparent 0%,
        rgba(255, 255, 255, 0) 20%,
        rgba(255, 255, 255, 0.45) 50%,
        rgba(255, 255, 255, 0) 80%,
        transparent 100%
    );
    transform: skewX(-22deg);
    pointer-events: none;
    z-index: 1;
}
.mm-hamburger.is-tap-hover::after {
    animation: mm-shine-sweep 0.45s cubic-bezier(.4, 0, .2, 1) forwards;
}
@keyframes mm-shine-sweep {
    from { left: -120%; }
    to   { left: 160%; }
}
.mm-hamburger.is-tap-hover {
    transform: translateY(-2px) scale(1.04);
    animation-play-state: paused;
    box-shadow:
        0 14px 34px rgba(var(--color-primary-rgb, 213, 21, 34), 0.55),
        inset 0 1px 0 rgba(255, 255, 255, 0.28),
        inset 0 -1px 0 rgba(0, 0, 0, 0.22);
}
.mm-hamburger.is-tap-press { transform: translateY(0) scale(0.92); }
.mm-hamburger:focus-visible {
    outline: 2px solid rgba(255, 255, 255, 0.7);
    outline-offset: 2px;
}
.mm-hamburger.is-open { animation: none; }

/* Note on the admin front-topbar (application/views/Front/_partials/admin-front-bubble.php):
 * it's `position:fixed; top:0; height:36px` at z-index 1000006, but renders with
 * `opacity:0; pointer-events:none` until JS adds .is-visible (hover/active state).
 * We deliberately DO NOT offset the hamburger to clear it — pushing it down 48px
 * created a visible gap below the header even when the topbar was invisible. The
 * trade-off: when an admin hovers the bubble to reveal the topbar, it'll briefly
 * cover the hamburger. The drawer (z-index 1000010) always covers everything. */
.mm-hamburger .bar {
    position: absolute;
    left: 50%; top: 50%;
    height: 2.5px;
    background: #fff;
    border-radius: 2px;
    transform-origin: center;
    transition:
        transform 0.42s cubic-bezier(.68, -0.4, .27, 1.45),
        opacity 0.22s ease,
        width 0.34s cubic-bezier(.34, 1.56, .64, 1);
    z-index: 2;
}
.mm-hamburger .bar:nth-child(1) { width: 19px; transform: translate(-50%, calc(-50% - 6px)); transition-delay: 0.04s; }
.mm-hamburger .bar:nth-child(2) { width: 14px; transform: translate(-50%, -50%);              transition-delay: 0s;    }
.mm-hamburger .bar:nth-child(3) { width: 11px; transform: translate(-50%, calc(-50% + 6px)); transition-delay: 0.1s;  }
.mm-hamburger.is-tap-hover .bar:nth-child(2),
.mm-hamburger.is-tap-hover .bar:nth-child(3) { width: 19px; }
.mm-hamburger.is-open .bar:nth-child(1) { width: 19px; transform: translate(-50%, -50%) rotate(45deg);  transition-delay: 0.06s; }
.mm-hamburger.is-open .bar:nth-child(2) { opacity: 0; transform: translate(-50%, -50%) scaleX(0);       transition-delay: 0s;    }
.mm-hamburger.is-open .bar:nth-child(3) { width: 19px; transform: translate(-50%, -50%) rotate(-45deg); transition-delay: 0.14s; }

/* =============================================================================
 * Drawer host + overlay (production: fixed, not absolute-in-phone-frame)
 * ============================================================================= */
.mm-host {
    position: fixed;
    inset: 0;
    /* Above the admin front-topbar (z-index 1000006) so the open drawer covers
     * the entire viewport — including any admin chrome — for a clean fullscreen
     * mobile experience. The topbar reappears when the drawer is closed. */
    z-index: 1000010;
    pointer-events: none;
    display: none;       /* hidden at desktop; ≤992px media query reveals it */
}
.mm-host.is-open { pointer-events: auto; }
.mm-overlay {
    position: absolute;
    inset: 0;
    background: rgba(15, 23, 42, 0.45);
    opacity: 0;
    transition: opacity 0.32s cubic-bezier(.2, .8, .2, 1);
    cursor: pointer;
}
.mm-host.is-open .mm-overlay { opacity: 1; }

.mm-host .mm-drawer {
    position: absolute;
    top: 0; bottom: 0; right: 0;
    width: 100%;
    max-width: 100vw;
    z-index: 1;
    transform: translate3d(100%, 0, 0);
    transition: transform 0.36s cubic-bezier(.2, .8, .2, 1);
    will-change: transform;
    background: var(--color-body, #ffffff);
    overflow: hidden;
}
.mm-host.is-open .mm-drawer { transform: translate3d(0, 0, 0); }

/* On larger phones / small tablets, drawer becomes a side panel rather than
 * full-bleed. The page is dimmed by the overlay on the left. */
@media (min-width: 600px) and (max-width: 992px) {
    .mm-host .mm-drawer {
        width: 440px;
        border-left: 1px solid #e6e6e3;
    }
}

/* =============================================================================
 * Panels (drill-down stack)
 * ============================================================================= */
.mm-panel {
    position: absolute;
    inset: 0;
    padding: 0;
    display: flex;
    flex-direction: column;
    background: var(--color-body, #ffffff);
    transform: translate3d(100%, 0, 0);
    transition: transform 0.32s cubic-bezier(.2, .8, .2, 1);
    will-change: transform;
    font-family: var(--body-font-family, 'Inter'), -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: var(--color-text, #1a1a1a);
}
.mm-panel.is-active { transform: translate3d(0, 0, 0); }
.mm-panel.is-prev   { transform: translate3d(-100%, 0, 0); }

/* Panel header (sticky top) */
.mm-head {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 18px 18px 14px;
    border-bottom: 1px solid #f0efec;
    background: var(--color-body, #ffffff);
    flex-shrink: 0;
    min-height: 64px;
}
.mm-head--root { padding: 5px 15px; }
.mm-head .mm-logo {
    max-height: 40px;
    width: auto;
    display: block;
}
.mm-head .mm-logo img { max-height: 40px !important; width: auto !important; display: block !important; }
.mm-head .mm-title {
    font-size: 16px;
    font-weight: 700;
    letter-spacing: -0.005em;
    color: var(--color-text, #1a1a1a);
    margin: 0;
    flex: 1;
    text-align: center;
}

/* Close + Back buttons — glassmorphic accent-tinted at rest, fill solid accent on tap. */
.mm-head .mm-back,
.mm-head .mm-close {
    border: 1px solid rgba(var(--color-primary-rgb, 213, 21, 34), 0.2);
    background: rgba(var(--color-primary-rgb, 213, 21, 34), 0.08);
    width: 42px; height: 42px;
    border-radius: var(--button-radius, 12px);
    display: inline-flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    color: var(--color-primary, #d51522);
    font-family: var(--body-font-family, 'Inter'), -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    font-size: 13px;
    font-weight: 700;
    letter-spacing: 0.04em;
    transition:
        background 0.28s ease,
        color 0.28s ease,
        transform 0.28s cubic-bezier(.34, 1.56, .64, 1),
        box-shadow 0.28s ease,
        border-color 0.28s ease;
    flex-shrink: 0;
    position: relative;
    overflow: hidden;
    box-shadow:
        inset 0 1px 0 rgba(255, 255, 255, 0.85),
        inset 0 -1px 0 rgba(var(--color-primary-rgb, 213, 21, 34), 0.1),
        0 1px 3px rgba(var(--color-primary-rgb, 213, 21, 34), 0.1);
}
.mm-head .mm-back::before,
.mm-head .mm-close::before {
    content: "";
    position: absolute;
    inset: 0;
    background: radial-gradient(circle at 50% 50%, rgba(var(--color-primary-rgb, 213, 21, 34), 0.08) 0%, transparent 65%);
    pointer-events: none;
    transition: opacity 0.28s ease;
}
.mm-head .mm-back.is-tap-hover,
.mm-head .mm-close.is-tap-hover {
    background: linear-gradient(90deg,
        var(--color-primary, #d51522) 0%,
        var(--color-primary_hover, #e61938) 100%);
    color: #fff;
    border-color: transparent;
    transform: scale(1.06);
    box-shadow:
        0 10px 25px rgba(var(--color-primary-rgb, 213, 21, 34), 0.3),
        inset 0 1px 0 rgba(255, 255, 255, 0.22),
        inset 0 -1px 0 rgba(0, 0, 0, 0.15);
}
.mm-head .mm-back.is-tap-hover::before,
.mm-head .mm-close.is-tap-hover::before { opacity: 0; }
.mm-head .mm-back.is-tap-press,
.mm-head .mm-close.is-tap-press { transform: scale(0.92); }
.mm-head .mm-close.is-tap-hover svg { transform: rotate(180deg); }
.mm-head .mm-back.is-tap-hover svg  { transform: translateX(-3px); }
.mm-head .mm-back {
    width: auto;
    padding: 0 16px;
    gap: 8px;
    border-radius: var(--button-radius, 12px);
}
.mm-head .mm-back svg,
.mm-head .mm-close svg {
    width: 18px; height: 18px;
    stroke: currentColor;
    stroke-width: 2.5;
    fill: none;
    transition: transform 0.36s cubic-bezier(.34, 1.56, .64, 1);
}

/* Panel body — scrollable flex column. CTA + foot live inside this region
 * (not as siblings of .mm-body) so they scroll along with cards when total
 * content exceeds the viewport height. A flex-grow spacer (.mm-body-spacer)
 * anchors CTA/foot to the panel bottom when there's room, and collapses to
 * zero when content overflows. This makes tall footer templates work without
 * being clipped by the drawer's overflow:hidden. */
.mm-body {
    flex: 1 1 auto;
    min-height: 0;
    overflow-y: auto;
    -webkit-overflow-scrolling: touch;
    padding: 8px 0;
    display: flex;
    flex-direction: column;
}
/* The spacer: grows to fill empty space when content is short (pushing the
 * CTA + foot to the panel bottom); collapses to 0 when content overflows
 * (so everything scrolls naturally with no awkward gap above the foot). */
.mm-body-spacer {
    flex: 1 0 auto;
    min-height: 0;
}

/* =============================================================================
 * Nav card — modernised. Soft accent-tinted surface at rest, prominent
 * gradient icon container, refined hover (lift + icon-scale + arrow-slide)
 * and press (primary border + filled background). Lucide icons inside.
 * Every accent colour derives from --color-primary so cards adapt to the
 * tenant's brand.
 * ============================================================================= */
.mm-cards {
    display: flex;
    flex-direction: column;
    gap: 8px;
    padding: 12px 12px 8px;
}
.mm-card {
    display: flex;
    align-items: center;
    text-align: left;
    gap: 14px;
    padding: 12px 14px;
    width: 100%;
    background: rgba(var(--color-primary-rgb, 213, 21, 34), 0.025);
    border: 1px solid rgba(var(--color-primary-rgb, 213, 21, 34), 0.06);
    border-radius: 14px;
}
/* Cards without an icon (admin didn't set one) — use a slightly slimmer
 * left padding so the label sits closer to the edge. Keeps the icon-less
 * cards from looking like they have an empty space on the left. */
.mm-card.mm-card--no-icon {
    padding-left: 18px;
}

/* Custom drawer body. When a tenant sets `mobile_navbar_template` (shortcode HTML),
 * its resolved markup is rendered here inside the new drawer chrome (instead of
 * the auto-generated cards). Tenants get full control over the body — we just
 * provide breathing room and basic overflow handling. */
.mm-custom-content {
    padding: 16px;
}
.mm-custom-content img { max-width: 100%; height: auto; }
.mm-custom-content > *:first-child { margin-top: 0; }
.mm-custom-content > *:last-child  { margin-bottom: 0; }

/* Drawer foot. Anchored to the bottom of the root panel by the flex spacer
 * (.mm-body-spacer) when there's room; scrolls naturally with content when
 * the foot is tall. Sourced from the mobile_navbar.footer_template setting
 * — tenants use this for footer-menu links, social icons, copyright,
 * language switcher, etc. We provide a soft top border + breathing padding;
 * the rest is up to the template author. */
.mm-foot {
    /* flex-shrink: 0 was here when .mm-foot sat outside .mm-body; now it
     * lives inside the body's flex column and we want it to honour overflow,
     * not force the panel to clip when the template is tall. */
    padding: 16px 18px 22px;
    margin-top: 25px;
    border-top: 1px solid rgba(0, 0, 0, 0.06);
    font-size: 13px;
    color: var(--color-text, #1a1a1a);
}
.mm-foot > *:first-child { margin-top: 0; }
.mm-foot > *:last-child  { margin-bottom: 0; }
.mm-foot img { max-width: 100%; height: auto; }
.mm-foot a {
    color: var(--color-primary, #d51522);
    text-decoration: none;
}
.mm-foot a:hover {
    text-decoration: underline;
}

/* Mega menu panel content. When a Menus admin item is flagged is_mega_menu,
 * the drawer drills into a panel whose body is the raw mega_menu_template
 * HTML the admin authored (instead of a card list). The wrapper just gives
 * the HTML some breathing room + handles overflow on narrow viewports;
 * tenant-authored mega templates are responsible for their own internal
 * layout (column stacking on narrow widths, image sizing, etc.). */
.mm-mega-content {
    padding: 16px;
    overflow-x: auto;
    -webkit-overflow-scrolling: touch;
}
.mm-mega-content img { max-width: 100%; height: auto; }
.mm-mega-content > *:first-child { margin-top: 0; }
.mm-mega-content > *:last-child  { margin-bottom: 0; }
/* Mega menus often use desktop-grid wrappers. On a ≤440px panel we collapse
 * any multi-column rows to single column so content doesn't overflow. */
.mm-mega-content .row,
.mm-mega-content [class*="col-"] {
    display: block !important;
    width: 100% !important;
    flex: 0 0 100% !important;
    max-width: 100% !important;
    margin-left: 0 !important;
    margin-right: 0 !important;
    font-family: var(--body-font-family, 'Inter'), -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    text-align: left;
    cursor: pointer;
    text-decoration: none;
    color: var(--color-text, #1a1a1a);
    transition:
        background 0.25s cubic-bezier(.2, .8, .2, 1),
        border-color 0.25s cubic-bezier(.2, .8, .2, 1),
        transform 0.25s cubic-bezier(.2, .8, .2, 1),
        box-shadow 0.25s cubic-bezier(.2, .8, .2, 1);
}
.mm-card:hover {
    background: rgba(var(--color-primary-rgb, 213, 21, 34), 0.05);
    border-color: rgba(var(--color-primary-rgb, 213, 21, 34), 0.18);
    transform: translateY(-1px);
    box-shadow: 0 8px 24px -10px rgba(var(--color-primary-rgb, 213, 21, 34), 0.2);
}
/* :active doubles as touch-press feedback (no real hover on touch). */
.mm-card:active {
    transform: scale(0.985);
    background: rgba(var(--color-primary-rgb, 213, 21, 34), 0.1);
    border-color: var(--color-primary, #d51522);
    box-shadow:
        0 0 0 1px var(--color-primary, #d51522),
        0 12px 28px -10px rgba(var(--color-primary-rgb, 213, 21, 34), 0.25);
}

/* Icon container — gradient primary fill with a soft coloured glow */
.mm-card-icon {
    width: 44px;
    height: 44px;
    border-radius: 12px;
    background: linear-gradient(135deg,
        var(--color-primary, #d51522) 0%,
        var(--color-primary_hover, #e61938) 100%);
    color: #fff;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    box-shadow:
        0 4px 12px rgba(var(--color-primary-rgb, 213, 21, 34), 0.28),
        inset 0 1px 0 rgba(255, 255, 255, 0.22),
        inset 0 -1px 0 rgba(0, 0, 0, 0.12);
    transition:
        transform 0.25s cubic-bezier(.34, 1.56, .64, 1),
        box-shadow 0.25s cubic-bezier(.2, .8, .2, 1);
}
.mm-card:hover .mm-card-icon {
    transform: scale(1.06) rotate(-2deg);
    box-shadow:
        0 8px 20px rgba(var(--color-primary-rgb, 213, 21, 34), 0.4),
        inset 0 1px 0 rgba(255, 255, 255, 0.28),
        inset 0 -1px 0 rgba(0, 0, 0, 0.12);
}
.mm-card:active .mm-card-icon {
    transform: scale(0.96);
}
.mm-card-icon svg,
.mm-card-icon i {
    width: 22px;
    height: 22px;
    stroke: currentColor;
    stroke-width: 2;
    fill: none;
    stroke-linecap: round;
    stroke-linejoin: round;
}

/* Card text block */
.mm-card-body {
    flex: 1;
    display: flex;
    flex-direction: column;
    gap: 2px;
    min-width: 0;
}
.mm-card-name {
    font-size: var(--body-font-size, 17px);
    font-weight: 600;
    color: var(--color-text, #1a1a1a);
    letter-spacing: -0.01em;
    line-height: 1.25;
}
.mm-card-sub {
    font-size: 13px;
    color: #868279;
    font-weight: 400;
    line-height: 1.35;
}

/* Trailing arrow — slides right on hover */
.mm-card-arrow {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    color: var(--color-primary, #d51522);
    flex-shrink: 0;
    transition:
        transform 0.25s cubic-bezier(.2, .8, .2, 1),
        opacity 0.25s ease;
}
.mm-card:hover .mm-card-arrow {
    transform: translateX(4px);
    opacity: 1;
}
.mm-card-arrow svg,
.mm-card-arrow i {
    width: 20px;
    height: 20px;
    stroke: currentColor;
    stroke-width: 2.25;
    fill: none;
    stroke-linecap: round;
    stroke-linejoin: round;
}

/* CTA strip (Tier 1 only — receives $header_ctas_html from the site) */
.mm-cta-wrap {
    /* Lives inside .mm-body's flex column; the spacer above it (.mm-body-spacer)
     * anchors this and the foot to the panel bottom on short content and
     * collapses on overflow so a tall foot scrolls cleanly. */
    padding: 14px 20px 22px;
}
.mm-cta-wrap > a,
.mm-cta-wrap > button,
.mm-cta-wrap .btn {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 100%;
    margin: 0 0 8px;
}
.mm-cta-wrap > a:last-child,
.mm-cta-wrap > button:last-child,
.mm-cta-wrap .btn:last-child { margin-bottom: 0; }
.mm-cta-wrap .sg-nav.sg-navbar-ctas {
    display: block;
}

/* =============================================================================
 * Breakpoint: drawer + hamburger active at ≤992px; hide existing desktop nav
 * in that range so the two systems don't visually clash.
 * ============================================================================= */
@media (max-width: 992px) {
    .mm-hamburger { display: inline-flex; align-items: center; justify-content: center; }
    .mm-host      { display: block; }

    /* Hide existing desktop nav wrapper between 768-992 (it was previously
     * visible because .sg-navbar-expand-md expands at min-width:768px). */
    header#masterhead .sg-navbar-wrapper,
    header#masterhead .navbar-wrapper { display: none !important; }
    /* Also hide the legacy mobile brand — the drawer's own header carries the logo */
    .mobile-navbar-brand { display: block; }
}
@media (min-width: 993px) {
    /* Safety nets — drawer never renders at desktop */
    .mm-hamburger,
    .mm-host { display: none !important; }
}

/* === source: https://royalweedmi.com/assets/front/css/sgen-nav-enhancements.css?v=c0b8d1b652bbb60901c5e766d1f79594e3b7002c === */
/* =============================================================================
 * SGEN — Navigation icon + subtext enhancements (desktop)
 *
 * Styles the per-item icon (.sg-nav-item-icon) and subtext (.sg-nav-item-sub)
 * that the Menus admin lets tenants set via the sgIconSelect picker + subtext
 * input. Both fields are optional — when a menu item has no icon or no
 * subtext, the corresponding .sg-nav-item-icon / .sg-nav-item-sub element
 * isn't emitted at all (see FrontModel::get_navigation_html /
 * get_navigation_list_html), and the <li> only gets `.has-icon` / `.has-subtext`
 * classes when the respective field is set.
 *
 * Companion to:
 *   - assets/front/css/sgen-mobile-menu.css (mobile drawer surface)
 *   - assets/admin/js/sg-icon-select.js     (admin picker)
 *
 * Tenant tokens consumed: --color-primary, --color-primary-rgb,
 * --color-text, --body-font-family. All have inline fallbacks.
 * ============================================================================= */

/* The inner wrapper holds the label + subtext stacked vertically (only matters
 * when subtext is present; with just a label it collapses to a single line). */
.sg-nav-item .sg-nav-item-text {
    display: inline-flex;
    flex-direction: column;
    align-items: flex-start;
    line-height: 1.2;
    text-align: left;
}
.sg-nav-item .sg-nav-item-label {
    display: inline-block;
}
.sg-nav-item .sg-nav-item-sub {
    display: block;
    margin-top: 2px;
    font-size: 12px;
    font-weight: 400;
    letter-spacing: 0;
    line-height: 1.3;
    color: rgba(0, 0, 0, 0.55);
    opacity: 0.92;
}
/* Inside dark contexts (e.g. dark header), soften the subtext against the
 * inherited link colour. currentColor at 60% reads correctly on both light
 * and dark backgrounds. */
.sg-nav-item .sg-nav-item-sub {
    color: currentColor;
    opacity: 0.6;
}

/* Icon: small inline-flex wrapper before the text. The actual icon glyph
 * inherits its colour from the link via currentColor + adapts on hover/active
 * the same way the link colour does. */
.sg-nav-item .sg-nav-item-icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    margin-right: 8px;
    color: var(--color-primary, #d51522);
    transition: color 0.18s ease, transform 0.18s ease;
}
.sg-nav-item .sg-nav-item-icon svg,
.sg-nav-item .sg-nav-item-icon i {
    width: 18px;
    height: 18px;
    stroke: currentColor;
    stroke-width: 2;
    fill: none;
    stroke-linecap: round;
    stroke-linejoin: round;
}
/* FontAwesome icons inherit colour but use fill, not stroke. */
.sg-nav-item .sg-nav-item-icon i.fa,
.sg-nav-item .sg-nav-item-icon i.fas,
.sg-nav-item .sg-nav-item-icon i.far,
.sg-nav-item .sg-nav-item-icon i.fab,
.sg-nav-item .sg-nav-item-icon i.fal,
.sg-nav-item .sg-nav-item-icon i.fad,
.sg-nav-item .sg-nav-item-icon i.fat {
    font-size: 16px;
    line-height: 1;
    width: auto;
    height: auto;
}
.sg-nav-item:hover .sg-nav-item-icon,
.sg-nav-item.active .sg-nav-item-icon {
    color: var(--color-primary_hover, #e61938);
    transform: scale(1.08);
}

/* When the link contains the icon+text inline, ensure proper vertical alignment.
 * The Bootstrap-style nav links use flex implicitly via .sg-nav-link / .sg-nav-link-item;
 * we don't override their flex direction — just align our inline wrapper. */
.sg-nav-item .sg-nav-item-link,
.sg-nav-item .sg-nav-link {
    display: inline-flex;
    align-items: center;
    gap: 0;   /* gap between icon and text is controlled by .sg-nav-item-icon margin */
}

/* In dropdown / mega-menu contexts where items typically stack vertically,
 * the subtext is more useful and the icon container can be a bit larger. */
.sg-dropdown-menu .sg-nav-item .sg-nav-item-icon,
.nav-submenu .sg-nav-item .sg-nav-item-icon,
.nav-item-mega-menu .sg-nav-item .sg-nav-item-icon {
    margin-right: 10px;
}
.sg-dropdown-menu .sg-nav-item .sg-nav-item-icon svg,
.sg-dropdown-menu .sg-nav-item .sg-nav-item-icon i,
.nav-submenu .sg-nav-item .sg-nav-item-icon svg,
.nav-submenu .sg-nav-item .sg-nav-item-icon i,
.nav-item-mega-menu .sg-nav-item .sg-nav-item-icon svg,
.nav-item-mega-menu .sg-nav-item .sg-nav-item-icon i {
    width: 20px;
    height: 20px;
}
.sg-dropdown-menu .sg-nav-item .sg-nav-item-sub,
.nav-submenu .sg-nav-item .sg-nav-item-sub,
.nav-item-mega-menu .sg-nav-item .sg-nav-item-sub {
    font-size: 13px;
    margin-top: 3px;
}

/* -----------------------------------------------------------------------------
 * Nested submenus (desktop flyout)
 *
 * A second-level menu (`.sg-dropdown-submenu`, emitted by
 * FrontModel::get_navigation_html when depth > 1) is `position: absolute` via
 * its base `.sg-dropdown-menu` rule but carries no offsets, so it lands at its
 * static position and stacks ON TOP of the parent menu's items. Its parent
 * `<li class="sg-dropdown">` is already `position: relative`, so we just push
 * the submenu out to the side instead of overlapping.
 *
 * The hover-to-open behaviour already cascades through
 * `.sg-site-navigation.sg-navbar-nav .sg-dropdown:hover > .sg-dropdown-menu`
 * (main.css), and this applies at every depth since each level's submenu flies
 * out from its own relatively-positioned parent. */
@media screen and (min-width: 768px) {
    .sg-dropdown-menu .sg-dropdown-submenu {
        top: 0;
        left: 100%;
        right: auto;
        /* Pull up by the parent menu's 0.5rem top padding so the submenu's
         * first item lines up with the parent item it flew out from. */
        margin-top: -0.5rem;
        /* Small overlap removes the dead hover gap between parent and submenu. */
        margin-left: -1px;
    }

    /* When the parent dropdown sits near the right viewport edge, a tenant can
     * flip the flyout to the left by adding `.sg-dropdown-submenu-left` to the
     * submenu <ul> (or `.opens-left` to the parent <li>). */
    .sg-dropdown-menu .sg-dropdown-submenu.sg-dropdown-submenu-left,
    .sg-dropdown-menu .sg-dropdown.opens-left > .sg-dropdown-submenu {
        left: auto;
        right: 100%;
        margin-left: 0;
        margin-right: -1px;
    }
}

/* In a top-level horizontal nav, force the text wrapper to single-line so a
 * subtext doesn't stretch the navbar vertically. The subtext still renders
 * but on a tighter line-height. Override by adding `.sg-nav-has-subtext` if
 * a tenant wants the subtext visible in the top bar. */
.sg-navbar > .sg-nav.sg-navbar-nav > .sg-nav-item.has-subtext .sg-nav-item-text {
    flex-direction: column;
    line-height: 1.15;
}

/* === source: https://royalweedmi.com/assets/defaults/sgen/assets/css/sg-drawer.css?v=c0b8d1b652bbb60901c5e766d1f79594e3b7002c === */
/* =============================================================================
 * sg-drawer — reusable offcanvas/drawer for SGEN-CMS modules.
 *
 *   Markup pattern:
 *
 *     <div class="sg-drawer-host" id="myDrawer" data-sg-side="right">
 *         <div class="sg-drawer-overlay" data-sg-drawer-close></div>
 *         <aside class="sg-drawer" role="dialog" aria-modal="true">
 *             <header class="sg-drawer-head">
 *                 <h3>Title</h3>
 *                 <button class="sg-drawer-close" data-sg-drawer-close>...</button>
 *             </header>
 *             <div class="sg-drawer-body">...</div>
 *             <footer class="sg-drawer-foot">...</footer>
 *         </aside>
 *     </div>
 *
 *     <button data-sg-drawer-open="myDrawer">Open</button>
 *
 *   Notes:
 *   - data-sg-side accepts "right" (default) or "left".
 *   - The host element is moved to <body> on first interaction to escape any
 *     ancestor with `transform`/`overflow:hidden` that would scope the
 *     position:fixed positioning.
 *   - Body scroll-lock is applied automatically while any drawer is open.
 *   - Inner chrome (head/body/foot) is opt-in — use the classes if you want
 *     the default look, otherwise put your own markup inside .sg-drawer.
 * ============================================================================= */

.sg-drawer-host {
    position: fixed; inset: 0;
    z-index: 10001;
    pointer-events: none;
}
.sg-drawer-host.is-open { pointer-events: auto; }

.sg-drawer-overlay {
    position: absolute; inset: 0;
    background: rgba(15, 23, 42, .5);
    opacity: 0;
    transition: opacity .28s cubic-bezier(.2, .8, .2, 1);
}
.sg-drawer-host.is-open .sg-drawer-overlay { opacity: 1; }

.sg-drawer {
    position: absolute; top: 0; bottom: 0;
    width: 440px; max-width: 100vw;
    background: #fff; color: #1f2937;
    display: flex; flex-direction: column;
    box-shadow: -16px 0 32px rgba(15, 23, 42, .18);
    transform: translate3d(100%, 0, 0);
    transition: transform .32s cubic-bezier(.2, .8, .2, 1);
    will-change: transform;
}
.sg-drawer-host[data-sg-side="left"] .sg-drawer {
    left: 0; right: auto;
    transform: translate3d(-100%, 0, 0);
    box-shadow: 16px 0 32px rgba(15, 23, 42, .18);
}
.sg-drawer-host[data-sg-side="right"] .sg-drawer,
.sg-drawer-host:not([data-sg-side]) .sg-drawer { right: 0; left: auto; }

.sg-drawer-host.is-open .sg-drawer { transform: translate3d(0, 0, 0); }

/* Body scroll-lock — applied by sg-drawer.js while any drawer is open. */
body.sg-drawer-locked { overflow: hidden; }

/* ---- Default chrome (opt-in) --------------------------------------------- */
.sg-drawer-head {
    display: flex; align-items: center; justify-content: space-between;
    padding: 1.25rem 1.5rem;
    border-bottom: 1px solid rgba(15, 23, 42, .08);
    flex: none;
}
.sg-drawer-head h3 {
    font-size: 1.05rem; margin: 0;
    font-weight: 700; letter-spacing: -.01em;
}
.sg-drawer-close {
    width: 36px; height: 36px;
    display: inline-flex; align-items: center; justify-content: center;
    background: transparent; border: 0; cursor: pointer;
    border-radius: 10px; color: inherit; opacity: .55;
    transition: opacity .15s ease, background .15s ease;
}
.sg-drawer-close:hover { opacity: 1; background: rgba(15, 23, 42, .06); }
.sg-drawer-body {
    flex: 1 1 auto;
    overflow-y: auto;
    padding: .5rem 1.5rem;
    -webkit-overflow-scrolling: touch;
}
.sg-drawer-foot {
    flex: none;
    padding: 1.25rem 1.5rem 1.5rem;
    border-top: 1px solid rgba(15, 23, 42, .08);
    display: flex; flex-direction: column; gap: .75rem;
    background: linear-gradient(180deg, rgba(15, 23, 42, .015) 0%, transparent 100%);
}

/* Reduced motion — instant slide instead of transitions. */
@media (prefers-reduced-motion: reduce) {
    .sg-drawer-overlay,
    .sg-drawer { transition: none !important; }
}

/* === source: https://royalweedmi.com/assets/front/css/locations.css?v=c0b8d1b652bbb60901c5e766d1f79594e3b7002c === */
/*
 * Locations module — base styling for the front-end blocks: the
 * [location_selector] surfaces and the SG Builder location components
 * (Location Selector/Field/Cards/Archive/Content/Title/Heading/CTA/Selection
 * Button, incl. the recreated legacy dl-* / .sgDispenzaLocation markup).
 *
 * Deliberately neutral and themeable — accents read the site's CSS custom
 * properties (with sensible fallbacks) so a tenant's own custom CSS
 * (site_additional_css) keeps overriding fonts/colours. Loaded sitewide via
 * FrontModel when the LOCATIONS module is enabled. The picker modal/drawer
 * lives in locations-picker.css.
 */

:root {
    --loc-accent: var(--sg-color-primary, #4d5839);
    --loc-accent-contrast: #ffffff;
    --loc-card-bg: #ffffff;
    --loc-border: #e6e6e6;
    --loc-radius: 12px;
    --loc-muted: #6b7280;
}

/* ---------------------------------------------------------------------------
 * [location_selector] — dropdown / list / grid / step-flow
 * ------------------------------------------------------------------------- */
.location-selector-wrap { display: block; }

.location-selector {
    width: 100%;
    max-width: 420px;
    padding: 10px 14px;
    border: 1px solid var(--loc-border);
    border-radius: 8px;
    background: var(--loc-card-bg);
    font: inherit;
    color: inherit;
}

.location-selector-list { list-style: none; margin: 0; padding: 0; display: grid; gap: 8px; }
.location-selector-item > a {
    display: block;
    padding: 12px 16px;
    border: 1px solid var(--loc-border);
    border-radius: var(--loc-radius);
    background: var(--loc-card-bg);
    color: inherit;
    text-decoration: none;
    transition: border-color .15s ease, box-shadow .15s ease;
}
.location-selector-item > a:hover,
.location-selector-item.is-active > a { border-color: var(--loc-accent); box-shadow: 0 0 0 1px var(--loc-accent) inset; }

.location-selector-grid { display: grid; gap: 12px; }

.location-selector-card {
    display: block;
    padding: 16px;
    border: 1px solid var(--loc-border);
    border-radius: var(--loc-radius);
    background: var(--loc-card-bg);
    color: inherit;
    text-decoration: none;
    text-align: center;
    transition: border-color .15s ease, box-shadow .15s ease, transform .1s ease;
}
.location-selector-card:hover { border-color: var(--loc-accent); transform: translateY(-1px); }
.location-selector-card.is-active { border-color: var(--loc-accent); box-shadow: 0 0 0 2px var(--loc-accent) inset; }

.location-selector-group { margin-bottom: 18px; }
.location-selector-group-title { font-weight: 700; margin: 0 0 8px; }

/* Step-flow panels */
.location-selector-steps { position: relative; overflow: hidden; }
.location-selector-steps-track { position: relative; }
.location-selector-panel[hidden] { display: none; }
.location-selector-step-title { font-weight: 700; font-size: 1.1em; margin: 0 0 12px; }
.location-selector-step-cards { display: grid; grid-template-columns: repeat(auto-fill, minmax(180px, 1fr)); gap: 12px; }
.location-selector-back {
    background: none; border: 0; padding: 4px 0; margin-bottom: 8px;
    color: var(--loc-accent); cursor: pointer; font: inherit;
}

/* [location_field] rich output */
.location-hours { list-style: none; margin: 0; padding: 0; }
.location-hours li { padding: 2px 0; }
.location-gallery { display: grid; grid-template-columns: repeat(auto-fill, minmax(120px, 1fr)); gap: 8px; }
.location-gallery-item img { width: 100%; height: auto; border-radius: 8px; display: block; }
.location-image { max-width: 100%; height: auto; border-radius: var(--loc-radius); }
.location-map-embed iframe { width: 100%; min-height: 320px; border: 0; border-radius: var(--loc-radius); }

/* ---------------------------------------------------------------------------
 * SG Builder location components (incl. recreated legacy dl-* markup)
 * ------------------------------------------------------------------------- */

/* Generic card tile shared by Archive Locations + Location Cards */
.dispenzaLocation-itemCard,
.sgDispenzaLocation-selection-locations .item,
.dl-location-cards .item {
    display: flex;
    flex-direction: column;
    background: var(--loc-card-bg);
    border: 1px solid var(--loc-border);
    border-radius: var(--loc-radius);
    overflow: hidden;
    height: 100%;
}
.dispenzaLocation-itemCard .image img,
.dl-location-cards .item .image img,
.sgDispenzaLocation-selection-locations .item .image img {
    width: 100%; height: auto; display: block; object-fit: cover;
}
.dispenzaLocation-itemCard .content,
.dl-location-cards .item .content,
.sgDispenzaLocation-selection-locations .item .content { padding: 18px; display: flex; flex-direction: column; gap: 8px; }
.dispenzaLocation-itemCard .title,
.dl-location-cards .item .title,
.sgDispenzaLocation-selection-locations .item .title { font-weight: 700; font-size: 1.25em; line-height: 1.2; }
.dispenzaLocation-itemCard .subtitle,
.dl-location-cards .item .subtitle { color: var(--loc-muted); font-size: .9em; }
.dispenzaLocation-itemCard .details,
.dl-location-cards .item .text { color: var(--loc-muted); }
.dispenzaLocation-itemCard .ctas,
.dl-location-cards .item .ctas { margin-top: auto; display: flex; flex-wrap: wrap; gap: 8px; }

/* Grid layout for Location Cards (non-carousel) */
.dl-cards-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(240px, 1fr)); gap: 20px; }

/* Buttons emitted by the location blocks */
.dispenzaLocation-itemCard .btn,
.dl-location-cards .btn,
.dl-cta,
.sgDispenzaLocation-selection-locations .ctas a {
    display: inline-block;
    padding: 12px 26px;
    border-radius: 999px;
    background: var(--loc-accent);
    color: var(--loc-accent-contrast);
    text-decoration: none;
    font-weight: 600;
    line-height: 1.2;
    border: 1px solid var(--loc-accent);
    cursor: pointer;
}
.dispenzaLocation-itemCard .btn:hover,
.dl-location-cards .btn:hover,
.dl-cta:hover { filter: brightness(.95); }

/* Location Content / Title / Heading */
.dl-content { display: block; }
.dl-title { font-weight: 600; }
.dl-heading { line-height: 1.15; }

/* Location Selection Button (navbar switcher) */
.sgDispenzaLocation--selection-btn { display: inline-block; }
.sgDispenzaLocation--selection-btn > a {
    display: inline-flex;
    flex-direction: column-reverse;
    align-items: center;
    justify-content: center;
    gap: 2px;
    padding: 8px 22px;
    border-radius: 999px;
    background: var(--loc-accent);
    color: var(--loc-accent-contrast);
    text-decoration: none;
    line-height: 1.15;
}
.sgDispenzaLocation--selection-btn .locname { font-weight: 600; }
.sgDispenzaLocation--selection-btn .sub { font-size: .72em; opacity: .85; }

/* Builder-canvas empty-state hint (also harmless on the front) */
.sg-builder-empty {
    padding: 16px 18px;
    border: 1px dashed var(--loc-border);
    border-radius: var(--loc-radius);
    color: var(--loc-muted);
    background: #fafafa;
    font-size: .95em;
}

/* === source: https://royalweedmi.com/assets/front/css/locations-picker.css?v=c0b8d1b652bbb60901c5e766d1f79594e3b7002c === */
/*
 * Locations module — auto-prompt picker (modal + page interstitial) and
 * on-demand drawer styles. Loaded sitewide via FrontModel when the LOCATIONS
 * module is enabled. Card sub-components (.loc-picker-card, .loc-drawer-card)
 * are visually consistent so visitors get a coherent look across both
 * surfaces.
 */

/* ---- Modal / page interstitial -------------------------------------- */
.loc-picker-modal { position: fixed; inset: 0; z-index: 99998; display: flex; align-items: center; justify-content: center; padding: 1rem; }
.loc-picker-modal__backdrop { position: absolute; inset: 0; background: rgba(15, 23, 42, .55); backdrop-filter: blur(4px); }
.loc-picker-modal__inner { position: relative; background: #fff; color: #0f172a; max-width: 720px; width: 100%; max-height: 90vh; overflow: auto; border-radius: 14px; box-shadow: 0 24px 64px -16px rgba(15,23,42,.45); padding: 1.4rem 1.5rem 1.25rem; }
.loc-picker-modal__head { display: flex; align-items: flex-start; justify-content: space-between; gap: .75rem; margin-bottom: .25rem; }
.loc-picker-modal__title { font-size: 1.25rem; font-weight: 700; margin: 0; }
.loc-picker-modal__close { background: transparent; border: 0; font-size: 1.6rem; line-height: 1; color: #64748b; cursor: pointer; padding: 0 .25rem; }
.loc-picker-modal__close:hover { color: #0f172a; }
.loc-picker-modal__sub { color: #64748b; font-size: .9rem; margin: 0 0 1rem; }
.loc-picker-modal__count { display: inline-block; margin-left: .35rem; padding: .1rem .5rem; background: #f1f5f9; color: #475569; border-radius: 999px; font-size: .75rem; font-weight: 600; }
.loc-picker-modal__body { margin-bottom: .75rem; }
.loc-picker-modal__foot { display: flex; justify-content: flex-end; padding-top: .5rem; border-top: 1px solid #f1f5f9; }
.loc-picker-modal__skip { background: transparent; border: 0; color: #64748b; font-size: .9rem; cursor: pointer; padding: .35rem .5rem; }
.loc-picker-modal__skip:hover { color: #0f172a; text-decoration: underline; }
.loc-picker-modal__error { margin-top: .65rem; padding: .55rem .75rem; border-radius: 6px; background: #fef2f2; color: #b91c1c; font-size: .85rem; border: 1px solid #fecaca; }

/* Page mode — full-bleed interstitial. The picker IS the page until the
   visitor selects; no centred card, no rounded corners, no shadow. The
   solid backdrop hides the page content rendered behind. */
.loc-picker-modal--page { padding: 0; }
.loc-picker-modal--page .loc-picker-modal__backdrop { background: #fff; backdrop-filter: none; }
.loc-picker-modal--page .loc-picker-modal__inner { max-width: min(960px, 92vw); max-height: none; height: auto; border-radius: 0; box-shadow: none; padding: clamp(1.5rem, 4vw, 3rem) clamp(1rem, 4vw, 3rem); }
.loc-picker-modal--page .loc-picker-modal__title { font-size: clamp(1.5rem, 3vw, 2rem); }
.loc-picker-modal--page .loc-picker-modal__sub { font-size: 1rem; margin-bottom: 1.5rem; }

/* Picker layouts (flat-grid + step-flow) */
.loc-picker-grid { display: grid; gap: .75rem; grid-template-columns: repeat(auto-fill, minmax(220px, 1fr)); }
.loc-picker-steps__panel { padding: .25rem 0; }
.loc-picker-steps__title { font-size: .9rem; font-weight: 600; text-transform: uppercase; letter-spacing: .03em; color: #64748b; margin: 0 0 .75rem; }
.loc-picker-steps__cards { display: grid; gap: .65rem; grid-template-columns: repeat(auto-fill, minmax(200px, 1fr)); }
.loc-picker-steps__back { background: transparent; border: 0; color: #475569; font-size: .85rem; font-weight: 500; cursor: pointer; margin-bottom: .65rem; padding: 0; }
.loc-picker-steps__back:hover { color: #0f172a; }

/* Picker card (modal + page) */
.loc-picker-card { position: relative; display: flex; flex-direction: column; align-items: flex-start; gap: .25rem; padding: .9rem 1rem; border: 1px solid #e5e7eb; border-radius: 10px; background: #fff; text-align: left; cursor: pointer; transition: border-color .15s ease, box-shadow .15s ease, transform .15s ease; }
.loc-picker-card:hover { border-color: #cbd5e1; box-shadow: 0 6px 18px -10px rgba(15,23,42,.18); transform: translateY(-1px); }
.loc-picker-card.is-maint { background: #fffbeb; border-color: #fde68a; }
.loc-picker-card.is-maint:hover { background: #fef3c7; }
.loc-picker-card__name  { font-weight: 600; font-size: 1rem; color: #0f172a; }
.loc-picker-card__where { font-size: .85rem; color: #64748b; }
.loc-picker-card__addr  { font-size: .8rem; color: #64748b; }
.loc-picker-card__phone { font-size: .8rem; color: #64748b; }
.loc-picker-card__count { font-size: .8rem; color: #64748b; }
.loc-picker-card__pill  { position: absolute; top: .5rem; right: .65rem; font-size: .65rem; font-weight: 700; text-transform: uppercase; letter-spacing: .03em; padding: .15rem .55rem; border-radius: 999px; background: #fde68a; color: #92400e; }
.loc-picker-card[disabled], .loc-picker-card.is-busy { opacity: .55; cursor: progress; }

@media (max-width: 480px) {
    .loc-picker-modal__inner { padding: 1.1rem 1rem 1rem; }
    .loc-picker-modal__title { font-size: 1.1rem; }
}

/* ---- Drawer trigger button ------------------------------------------- */
/* .loc-picker-trigger carries the theme's .btn .btn-primary classes (see
   LocationsModel::pickerTriggerClass), so colours/padding/radius come from the
   site theme. Only the map-pin icon + label layout is defined here; sizes use
   `em` so they track the button's font-size. The label text is swapped to the
   selected location name client-side (locations-picker.js). */
.loc-picker-trigger { align-items: center; gap: .45em; white-space: nowrap; }
.loc-picker-trigger__icon { width: 1em; height: 1em; flex: 0 0 auto; }
.loc-picker-trigger__label { line-height: 1.2; }

/* ---- On-demand drawer ------------------------------------------------ */
.loc-drawer { width: 380px; max-width: 92vw; }
.loc-drawer__sub  { color: #64748b; font-size: .85rem; margin: 0 0 .85rem; }
.loc-drawer__list { display: flex; flex-direction: column; gap: .5rem; }
.loc-drawer__error { margin-top: .65rem; padding: .55rem .75rem; border-radius: 6px; background: #fef2f2; color: #b91c1c; font-size: .85rem; border: 1px solid #fecaca; }

.loc-drawer-card { position: relative; display: flex; flex-direction: column; align-items: flex-start; gap: .2rem; padding: .85rem 1rem; border: 1px solid #e5e7eb; border-radius: 10px; background: #fff; text-align: left; cursor: pointer; transition: border-color .15s ease, box-shadow .15s ease, transform .15s ease; width: 100%; }
.loc-drawer-card:hover { border-color: #cbd5e1; box-shadow: 0 4px 14px -8px rgba(15,23,42,.18); transform: translateY(-1px); }
.loc-drawer-card.is-maint { background: #fffbeb; border-color: #fde68a; }
.loc-drawer-card.is-maint:hover { background: #fef3c7; }
.loc-drawer-card__name  { font-weight: 600; font-size: .95rem; color: #0f172a; }
.loc-drawer-card__where { font-size: .8rem; color: #64748b; }
.loc-drawer-card__addr  { font-size: .8rem; color: #64748b; }
.loc-drawer-card__phone { font-size: .8rem; color: #64748b; }
.loc-drawer-card__pill  { position: absolute; top: .55rem; right: .65rem; font-size: .65rem; font-weight: 700; text-transform: uppercase; letter-spacing: .03em; padding: .15rem .55rem; border-radius: 999px; background: #fde68a; color: #92400e; }
.loc-drawer-card[disabled], .loc-drawer-card.is-busy { opacity: .55; cursor: progress; }

